old:
  set accommodation_unit_id = new_unit,
      updated_at = now()
where reservation.id = booking.id;

if not found or left_holder = entered_holder then
  return false;
end if;

new:
/*sabotage*/ select app.unit_status_holder((event.payload ->> 'fromUnitId')::uuid), property.id
  into left_holder, holder_property
  from outbox.events as event
  join public.accommodation_units as unit on unit.id = (event.payload ->> 'fromUnitId')::uuid
  join public.properties as property on property.id = unit.property_id
 where event.id = target_event_id and event.payload ? 'fromUnitId';
if left_holder is null then
  return false;
end if;
moved_at := coalesce(moved_at, now());
